echo "=== HACK: speed/tick/heights/alpha/line usage ==="
grep -n -E 'speed|tick|heights|glLineWidth|GL_LINE|glBlend|glColor|alpha|fg\[|buzz|frames|glCallList|glNewList|frame_count|gettimeofday|time|GL_BLEND|glEnable' firmware/src/hacks/unknownpleasures/unknownpleasures.c | head -120
echo "=== REGISTRY ==="
